Initial Data: table `products`, id=1, stock=10
Isolation Level: Repeatable Read (RR)

-- Time 1 (Tx A)
START TRANSACTION;
SELECT stock FROM products WHERE id=1; -- Returns 10

-- Time 2 (Tx B)
START TRANSACTION;
UPDATE products SET stock = 20 WHERE id=1;
COMMIT;

-- Time 3 (Tx A)
UPDATE products SET stock = stock - 1 WHERE id=1;
SELECT stock FROM products WHERE id=1;

// Pseudo-code in Application Layer

function withdraw(userId, amount) {
  // 1. Check balance
  currentBalance = db.query("SELECT balance FROM accounts WHERE id = ?", userId);

  if (currentBalance >= amount) {
    newBalance = currentBalance - amount;
    // 2. Update balance
    db.execute("UPDATE accounts SET balance = ? WHERE id = ?", newBalance, userId);
    return true;
  }
  return false;
}
